SET search_path TO lms, extensions;

-- Reassign existing lesson rows to a named Module in one transaction. The
-- session/progress/PDF foreign keys remain attached to those lesson rows.
CREATE OR REPLACE FUNCTION lms.save_track_module_group(
  target_track_id uuid,
  previous_group text,
  new_group text,
  lesson_ids uuid[]
) RETURNS void
LANGUAGE plpgsql SECURITY INVOKER SET search_path = '' AS $$
DECLARE
  old_name text := nullif(btrim(previous_group), '');
  next_name text := nullif(btrim(new_group), '');
  requested integer := coalesce(cardinality(lesson_ids), 0);
  affected integer;
  updated integer;
BEGIN
  IF NOT lms.has_admin_permission('manage_curriculum') THEN
    RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'Curriculum permission required';
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM lms.modules
    WHERE id = target_track_id AND parent_id IS NULL AND deleted_at IS NULL
  ) THEN
    RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'Track not found';
  END IF;

  IF requested = 0 AND old_name IS NULL THEN
    RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'Choose at least one lesson';
  END IF;
  IF requested > 0 AND (next_name IS NULL OR length(next_name) > 100) THEN
    RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'Module name must be 1 to 100 characters';
  END IF;
  IF (SELECT count(DISTINCT lesson_id) FROM unnest(lesson_ids) AS selected(lesson_id)) <> requested THEN
    RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'Duplicate lesson selection';
  END IF;
  IF (
    SELECT count(*) FROM lms.modules
    WHERE id = ANY(lesson_ids) AND parent_id = target_track_id AND deleted_at IS NULL
  ) <> requested THEN
    RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'Lessons must belong to this Track';
  END IF;
  IF old_name IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM lms.modules
    WHERE parent_id = target_track_id AND module_group = old_name AND deleted_at IS NULL
  ) THEN
    RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'Module no longer exists';
  END IF;
  IF next_name IS NOT NULL AND old_name IS DISTINCT FROM next_name AND EXISTS (
    SELECT 1 FROM lms.modules
    WHERE parent_id = target_track_id AND module_group = next_name AND deleted_at IS NULL
  ) THEN
    RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'A Module with this name already exists';
  END IF;

  SELECT count(*) INTO affected FROM lms.modules
  WHERE parent_id = target_track_id AND deleted_at IS NULL
    AND (id = ANY(lesson_ids) OR (old_name IS NOT NULL AND module_group = old_name));

  UPDATE lms.modules
  SET module_group = CASE WHEN id = ANY(lesson_ids) THEN next_name ELSE NULL END
  WHERE parent_id = target_track_id AND deleted_at IS NULL
    AND (id = ANY(lesson_ids) OR (old_name IS NOT NULL AND module_group = old_name));

  GET DIAGNOSTICS updated = ROW_COUNT;
  IF updated <> affected THEN
    RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'Could not update every selected lesson';
  END IF;
END;
$$;

REVOKE ALL ON FUNCTION lms.save_track_module_group(uuid, text, text, uuid[]) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION lms.save_track_module_group(uuid, text, text, uuid[]) TO authenticated;
